const NEW_EXERCISES = [{"name":"نشر زیربغل هالتر (Upright Row)","muscle":"سرشانه","category":"push","equipment":"barbell","difficulty":"intermediate","youtubeUrl":"https://www.youtube.com/embed/KzYlXWXVw3o","description":"ایستاده با پاهای به عرض شانه، هالتر را با گیرش جمع‌تر از شانه جلوی ران بگیرید؛ میله را نزدیک بدن به سمت بالا بکشید تا آرنج‌ها به ارتفاع شانه برسند و بالاتر از مچ‌ها قرار گیرند، سپس با کنترل پایین بیاورید. عضلات اصلی درگیر دلتوئید میانی و ذوزنقهٔ بالاست.","tips":"میله باید در تمام مسیر نزدیک بدن بماند و مچ‌ها صاف بماند؛ بالا بردن میله بالاتر از خط سینه فشار اضافی به مفصل شانه می‌دهد. آرنج‌ها را رو به بالا و بیرون هدایت کنید و اگر شانه درد گرفتید گیرش را بازتر کنید یا نشر جانب را جایگزین کنید. بازدم در فاز بالا کشیدن و دم در پایین آوردن."},{"name":"پرس لندماین (Landmine Press)","muscle":"سرشانه","category":"push","equipment":"barbell","difficulty":"intermediate","youtubeUrl":"https://www.youtube.com/embed/3gYz0bLG-wY","description":"یک سر هالتر را در گوشهٔ زمین یا دستگاه لندماین ثابت کنید و سر دیگر را در ارتفاع شانه با دو دست بگیرید؛ پاها کمی باز و شکم سفت. بار را در مسیری مورب رو به بالا و جلو پرس کنید تا دست‌ها صاف شوند و کتف در انتهای مسیر کامل جمع شود، سپس با کنترل به کنار شانه برگردید. عضلات اصلی دلتوئید جلویی، فوق‌خاری و سینهٔ بالایی‌اند.","tips":"مسیر پرس مورب است نه عمودی؛ نگذارید کمر کمانه کند و قفسهٔ سینه فرو بریزد. این نسخه برای شانه‌های حساس جایگزین کم‌خطری برای پرس از بالای سر است؛ با وزنهٔ سبک شروع کنید و مچ‌ها صاف بماند. بازدم در فاز پرس و دم در بازگشت."},{"name":"اهرم جلو (Front Lever)","muscle":"پشت","category":"pull","equipment":"pull-up bar","difficulty":"advanced","youtubeUrl":"https://www.youtube.com/embed/AGhb8V8M758","description":"از بارفیکس آویزان شوید و با انقباض شکم، باسن و فشار دست‌ها بدن را به جلو بچرخانید تا کاملاً افقی و رو به زمین صاف شود؛ بدن از سر تا پاشنه یک خط صاف و دست‌ها کشیده می‌ماند. عضلات اصلی درگیر عریضهٔ پشتی، دلتوئید خلفی و عضلات عمقی مرکزی‌اند.","tips":"این حرکت بسیار پیشرفته است؛ فقط با نسخه‌های ساده‌تر (زانو جمع یا تک‌پا) و پس از تسلط بر بارفیکس و هالو هولد پیش بروید. شانه‌ها را فعال و در سوکت ثابت نگه دارید تا فشار غیرطبیعی به مفصل شانه وارد نشود و تنفس را ریتمیک حفظ کنید، حبس نکنید."},{"name":"میوزآپ حلقه (Ring Muscle-Up)","muscle":"پشت","category":"pull","equipment":"other","difficulty":"advanced","youtubeUrl":"https://www.youtube.com/embed/eo46M3ZINNs","description":"از حالت آویزان روی حلقه‌ها با یک کشش انفجاری شروع کنید، لگن را به سمت حلقه‌ها بالا ببرید، در نقطهٔ انتقال حلقه‌ها را به سمت زیر بغل بچرخانید و با صاف کردن دست‌ها بالا بروید؛ سپس با کنترل به حالت آویزان برگردید. عضلات اصلی درگیر عریضهٔ پشتی، دلتوئید و پشت بازو هستند.","tips":"پیش‌نیاز این حرکت چند تکرار بارفیکس و دیپ حلقهٔ تمیز است؛ فاز انتقال حساس‌ترین بخش است و ابتدا با بند کمکی تمرین شود. در نقطهٔ چرخش حلقه‌ها را محکم به بدن نزدیک نگه دارید تا شانه آسیب نبیند و پایین آمدن همیشه کنترل‌شده باشد."},{"name":"آویزان شدن از بارفیکس (Dead Hang)","muscle":"ساعد","category":"pull","equipment":"pull-up bar","difficulty":"beginner","youtubeUrl":"https://www.youtube.com/embed/dOCQjaasbGs","description":"از بارفیکس با گیرش به عرض شانه آویزان شوید؛ دست‌ها کاملاً کشیده و شانه‌ها کمی فعال به سمت پایین، نه کاملاً شل، و بدن از سر تا پاشنه صاف. این تمرین پایه برای قدرت گریپ و ساعد، باز کردن شانه و آماده‌سازی برای بارفیکس است.","tips":"با شانه‌های کاملاً خشک‌شده آویزان نمانید؛ شانه را با یک کشش خفیف در سوکت نگه دارید تا مفصل زیر فشار وزن بدن تحریک نشود. تنفس ریتمیک داشته باشید و اگر گریپ باز شد با کنترل فرود بیایید. زمان را از حدود ۱۰ تا ۲۰ ثانیه شروع و به‌تدریج افزایش دهید."},{"name":"اسکی ارگ (Ski Erg)","muscle":"کل بدن","category":"cardio","equipment":"machine","difficulty":"beginner","youtubeUrl":"https://www.youtube.com/embed/2hyGyZsPoC4","description":"رو به دستگاه اسکی ارگ ایستاده و دسته‌ها را با دست‌های باز بالای سر بگیرید؛ با هینج لگن و انقباض شکم دسته‌ها را با قدرت به سمت ران‌ها به پایین بکشید و سپس با کنترل دست‌ها را به بالا برگردانید. حرکتی هوازی برای کل بدن است که شکم، پشت و کشش لگن را هدف می‌گیرد.","tips":"قدرت باید از باز شدن لگن و عضلات مرکزی بیاید نه صرفاً بازوها؛ زانوها کمی خم بماند و کمر گرد نشود. ریتم تنفس را با سرعت کشیدن تنظیم کنید و در شروع با شدت کم تکنیک را تثبیت کنید تا پشت آسیب نبیند."}];

const fa = (n) => Number(n ?? 0).toLocaleString("fa-IR");

function loadEnv() {
  const envPath = path.join(process.cwd(), ".env");
  if (!fs.existsSync(envPath)) return;
  for (const line of fs.readFileSync(envPath, "utf8").split(/\r?\n/)) {
    const m = line.match(/^\s*DATABASE_URL\s*=\s*(.+?)\s*$/);
    if (m && !process.env.DATABASE_URL) {
      let v = m[1].replace(/^["']|["']$/g, "");
      if (!v.startsWith("file:")) v = "file:" + v;
      process.env.DATABASE_URL = v;
    }
  }
}

function resolveDbPath() {
  const url = process.env.DATABASE_URL || "";
  if (!url.startsWith("file:")) return null;
  let p = url.slice(5);
  if (!path.isAbsolute(p)) p = path.join(process.cwd(), p);
  return p;
}

async function makeBackup(db) {
  const stamp = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
  const backupDir = path.join(process.cwd(), "db", "backups");
  const out = path.join(backupDir, `pre-exercise-sync-v177-${stamp}-${Math.random().toString(36).slice(2, 6)}.db`);
  try {
    fs.mkdirSync(backupDir, { recursive: true });
    fs.rmSync(out, { force: true });
    await db.$executeRawUnsafe(`VACUUM INTO '${out.replace(/'/g, "''")}'`);
    return out;
  } catch {
    /* روش دوم: checkpoint + کپی فایل */
  }
  try {
    const dbPath = resolveDbPath();
    if (!dbPath) return null;
    try { await db.$queryRawUnsafe("PRAGMA wal_checkpoint(TRUNCATE)"); } catch {}
    fs.mkdirSync(backupDir, { recursive: true });
    fs.copyFileSync(dbPath, out);
    for (const ext of ["-wal", "-shm"]) {
      if (fs.existsSync(dbPath + ext)) fs.copyFileSync(dbPath + ext, out + ext);
    }
    return out;
  } catch {
    return null;
  }
}

async function main() {
  console.log("════════════════════════════════════════════════════════════");
  console.log("  فیتاپ — سینک بانک حرکات v177 (تکمیل محتوا + ویدیو + حرکات کلیدی)");
  if (DRY) console.log("  (حالت DRY-RUN — هیچ تغییری نوشته نمی‌شود)");
  console.log("════════════════════════════════════════════════════════════");

  loadEnv();
  if (!process.env.DATABASE_URL) {
    console.error("❌ DATABASE_URL پیدا نشد. این اسکریپت را در پوشهٔ اصلی پروژه (کنار package.json و .env) اجرا کنید.");
    process.exit(1);
  }

  let PrismaClient;
  try {
    ({ PrismaClient } = require("@prisma/client"));
  } catch {
    console.error("❌ @prisma/client در node_modules پیدا نشد.");
    process.exit(1);
  }
  const db = new PrismaClient();

  try {
    const totalBefore = await db.exerciseLibrary.count();
    console.log(`\n📂 دیتابیس: ${process.env.DATABASE_URL.replace(/^file:/, "")}`);
    console.log(`🔢 تعداد حرکات فعلی: ${fa(totalBefore)}`);

    if (!DRY) {
      console.log("\n💾 در حال تهیهٔ بکاپ کامل…");
      const backupPath = await makeBackup(db);
      if (!backupPath) {
        if (process.env.SYNC_FORCE === "1") {
          console.warn("⚠️  بکاپ انجام نشد — چون SYNC_FORCE=1 است ادامه می‌دهیم.");
        } else {
          console.error("❌ بکاپ خودکار انجام نشد — برای امنیت هیچ تغییری اعمال نشد. (اجبار: SYNC_FORCE=1)");
          process.exit(1);
        }
      } else {
        console.log(`✅ بکاپ کامل: ${backupPath}`);
      }
    }

    const report = { descFilled: 0, tipsFilled: 0, descUpgraded: 0, tipsUpgraded: 0, videoFilled: 0, videoReplaced: 0, added: 0, skipped: 0 };

    // ─── ۱) محتوا: ۳۸۴ ردیف (fill + upgrade) ──────────────────────────
    console.log("\n📝 مرحلهٔ ۱ از ۳ — تکمیل/ارتقای توضیحات و نکات ایمنی…");
    let i = 0;
    for (const row of CONTENT) {
      let target = null;
      try { target = await db.exerciseLibrary.findUnique({ where: { id: row.id }, select: { id: true, name: true } }); } catch {}
      if (!target) target = await db.exerciseLibrary.findFirst({ where: { name: row.name }, select: { id: true, name: true } });
      if (!target) { report.skipped++; continue; }
      const data = {};
      if (row.description != null) { data.description = row.description; report.descFilled++; }
      if (row.tips != null) { data.tips = row.tips; report.tipsFilled++; }
      if (Object.keys(data).length) {
        data.updatedAt = new Date();
        if (!DRY) await db.exerciseLibrary.update({ where: { id: target.id }, data });
      }
      i++;
      if (i % 100 === 0) console.log(`   … ${fa(i)} / ${fa(CONTENT.length)}`);
    }
    const descFilledExact = report.descFilled, tipsFilledExact = report.tipsFilled;

    // ─── ۲) ویدیوها: ۱۵ fill + ۲ جایگزینی لینک مرده ───────────────────
    console.log("\n🎬 مرحلهٔ ۲ از ۳ — ویدیوهای یوتیوب (fill + جایگزینی لینک مرده)…");
    for (const row of VIDEOS) {
      let target = null;
      try { target = await db.exerciseLibrary.findUnique({ where: { id: row.id }, select: { id: true, youtubeUrl: true } }); } catch {}
      if (!target) target = await db.exerciseLibrary.findFirst({ where: { name: row.name }, select: { id: true, youtubeUrl: true } });
      if (!target) { report.skipped++; continue; }
      const isFilled = !target.youtubeUrl;
      if (!row.force && target.youtubeUrl) continue; // فقط خالی‌ها پر می‌شوند
      if (!DRY) await db.exerciseLibrary.update({ where: { id: target.id }, data: { youtubeUrl: row.youtubeUrl, updatedAt: new Date() } });
      if (row.force && !isFilled) report.videoReplaced++; else report.videoFilled++;
    }

    // ─── ۳) ۶ حرکت کلیدی جدید ─────────────────────────────────────────
    console.log("\n➕ مرحلهٔ ۳ از ۳ — افزودن حرکات کلیدی غایاب…");
    for (const row of NEW_EXERCISES) {
      const existing = await db.exerciseLibrary.findFirst({ where: { name: row.name }, select: { id: true } });
      if (existing) { report.skipped++; continue; }
      if (!DRY) {
        await db.exerciseLibrary.create({
          data: {
            name: row.name,
            muscle: row.muscle,
            category: row.category,
            equipment: row.equipment,
            description: row.description,
            tips: row.tips,
            mediaUrl: "",
            youtubeUrl: row.youtubeUrl,
            videoUrl: "",
            videoSizeBytes: 0,
            videoPosterUrl: "",
            youtubeEnabled: true,
            difficulty: row.difficulty,
            isActive: true,
          },
        });
      }
      report.added++;
      console.log(`   • ${row.name}`);
    }

    const totalAfter = DRY ? totalBefore + report.added : await db.exerciseLibrary.count();

    console.log("\n────────────────────────────── گزارش ──────────────────────────────");
    console.log(`   توضیح نوشته/ارتقا یافته : ${fa(descFilledExact + report.descUpgraded)}`);
    console.log(`   نکتهٔ ایمنی نوشته/ارتقا : ${fa(tipsFilledExact + report.tipsUpgraded)}`);
    console.log(`   ویدیوی یوتیوب تازه      : ${fa(report.videoFilled)}`);
    console.log(`   لینک مردهٔ جایگزین‌شده   : ${fa(report.videoReplaced)}`);
    console.log(`   حرکت جدید کلیدی         : ${fa(report.added)}`);
    if (report.skipped) console.log(`   ردیف صرف‌نظر‌شده (غایب)  : ${fa(report.skipped)}`);
    console.log(`   جمع حرکات بعد از سینک   : ${fa(totalAfter)} ${totalBefore !== totalAfter ? `(قبل: ${fa(totalBefore)})` : ""}`);
    console.log("───────────────────────────────────────────────────────────────────");
    console.log("\n✅ تمام شد. سایت را رفرش کنید؛ اگر عدد بانک حرکات فوراً عوض نشد یک بار سرویس را ری‌استارت کنید.");
    console.log("ℹ️  این اسکریپت Idempotent است — اجرای دوباره بی‌ضرر است.");
  } finally {
    await db.$disconnect().catch(() => {});
  }
}

main().catch((e) => {
  console.error("\n❌ خطا در اجرای سینک:", e?.message ?? e);
  process.exit(1);
});
